package net.officefloor.hq.app.rate;

import org.springframework.format.annotation.DateTimeFormat;
import net.officefloor.hq.app.history.SheetHistory;
import net.officefloor.hq.app.rollup.Rollup;
import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/** Rates on a sheet: each grade's, by from-date. The caller's signed-in name comes in the {@code X-User} header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/rates")
public class RateController {

    /** A grade's rate as the screen shows it: a percent with exactly two decimals, and the day it
     *  takes effect (null when it applies from the beginning of time) and the last day it applies
     *  (null when it does not end). */
    public record RateView(String grade, String rate, LocalDate from, LocalDate to) {

        public static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getRate().toPlainString(), rate.getFromDate(),
                    rate.getToDate());
        }
    }

    /** A rate as the form submits it: a percent of 0.00 or more with up to two decimals, and an
     *  optional from-date and to-date. */
    public record RateForm(@NotNull @DecimalMin("0.00") @Digits(integer = 3, fraction = 2) BigDecimal rate,
            LocalDate from, LocalDate to) {
    }

    private final RateService rates;
    private final SheetHistory history;

    public RateController(RateService rates, SheetHistory history) {
        this.history = history;
        this.rates = rates;
    }

    /** What a candidate rate for a grade, applied on every date, would change; nothing is saved. */
    @GetMapping("/{grade}/preview")
    public Rollup.RatePreview preview(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestParam @NotNull @DecimalMin("0.00") @Digits(integer = 3, fraction = 2) BigDecimal rate) {
        return rates.preview(sheetId, grade, rate);
    }

    @GetMapping
    public List<RateView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = SheetHistory.AS_OF_HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        if (asOf != null) {
            return history.viewsAsOf(sheetId, asOf).rates();
        }
        return rates.list(sheetId).stream().map(RateView::of).toList();
    }

    /** The rates of the sheet's ancestors, nearest first (its parent's, its parent's parent's, up to three levels
     *  up), each by grade in the order they take effect: a grade with no rate in force on a date on the sheet takes
     *  the first in force on that date up the line. As of a date, each as it stood then. */
    @GetMapping("/inherited")
    public List<List<RateView>> inherited(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = SheetHistory.AS_OF_HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        return rates.ancestorsOf(sheetId).stream()
                .map(ancestor -> asOf != null ? history.viewsAsOf(ancestor, asOf).rates()
                        : rates.list(ancestor).stream().map(RateView::of).toList())
                .toList();
    }

    @PutMapping("/{grade}")
    public RateView set(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody RateForm request) {
        return RateView.of(rates.set(sheetId, user, grade, request.from(), request.to(), request.rate()));
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The rate set for each grade on a sheet. */
@Service
public class RateService {

    private final RateRepository rates;
    private final SheetService sheets;
    private final Audit audit;
    private final Rollup rollup;
    private final RateChains chains;

    public RateService(RateRepository rates, SheetService sheets, Audit audit, Rollup rollup, RateChains chains) {
        this.chains = chains;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** The rates set on the sheet, by grade, each grade's in the order they take effect. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetId(sheetId).stream()
                .sorted(Comparator.comparing(Rate::getGrade).thenComparing(Rate.BY_FROM))
                .toList();
    }

    /** The ids of the sheet's ancestors whose rates stand in for its own, nearest first. */
    @Transactional(readOnly = true)
    public List<String> ancestorsOf(String sheetId) {
        return chains.ancestorsOf(sheetId);
    }

    /** What a candidate rate for a grade would change were it to apply on every date; nothing is stored. */
    @Transactional(readOnly = true)
    public Rollup.RatePreview preview(String sheetId, String grade, BigDecimal rate) {
        return rollup.preview(sheetId, grade, rate);
    }

    /** Set a grade's rate from a date (null: from the beginning of time) through a to-date (null: it
     *  does not end), replacing the rate it had from that same date, if any. A to-date before the
     *  from-date is refused. */
    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal rate) {
        if (from != null && to != null && to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A rate cannot end before it starts");
        }
        sheets.load(sheetId, user);
        BigDecimal scaled = rate.setScale(2, RoundingMode.UNNECESSARY);
        Rollup.Figures before = rollup.of(sheetId);
        Rate row = rates.findBySheetIdAndGrade(sheetId, grade).stream()
                .filter(r -> Objects.equals(r.getFromDate(), from))
                .findFirst()
                .orElseGet(() -> new Rate(sheetId, grade, from, scaled));
        row.setRate(scaled);
        row.setToDate(to);
        Rate saved = rates.saveAndFlush(row);
        audit.recordChangeOnCommit(sheetId, user, "RATE_SET sheet=" + sheetId + " by=" + user
                + " grade=" + saved.getGrade() + " rate=" + saved.getRate().toPlainString()
                + (from == null ? "" : " from=" + from)
                + (to == null ? "" : " to=" + to));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }
}
import { Component, inject, signal } from '@angular/core';
import { takeUntilDestroyed, toObservable } from '@angular/core/rxjs-interop';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { EMPTY, switchMap } from 'rxjs';
import { GRADES, Grade } from '../../core/people';
import { NOT_AVAILABLE, RATE_PATTERN, RatePreview, Rates } from '../../core/rates';
import { Sheets } from '../../core/sheet';

// The sheet's rates for each grade: the one in force today, each by from-date, and a form to set one.
@Component({
  selector: 'app-rates',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="rates-heading">
      <h2 id="rates-heading">Rates</h2>
      <ul aria-label="Rate for each grade">
        @for (g of grades; track g) {
          <li>
            Grade {{ g }}, today: <span [attr.data-testid]="'rate-current-' + g">{{ rates.byGrade().get(g) ?? notAvailable }}</span>
            <ul [attr.aria-label]="'Rates of grade ' + g">
              @for (r of rates.ratesByGrade().get(g) ?? []; track r.from) {
                <li [attr.data-testid]="'rate-row-' + g + '-' + (r.from ?? 'start')">
                  <span data-testid="rate-pct">{{ r.rate }}</span>% from {{ r.from ?? 'the start' }}
                  @if (r.to !== null) {
                    through <span data-testid="rate-to">{{ r.to }}</span>
                  }
                </li>
              }
            </ul>
          </li>
        }
      </ul>

      <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Set a rate">
        <label for="rate-form-grade">Grade</label>
        <select id="rate-form-grade" data-testid="rate-form-grade" formControlName="grade">
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <label for="rate-form-pct">Rate (%)</label>
        <input id="rate-form-pct" data-testid="rate-form-pct" formControlName="pct" inputmode="decimal" autocomplete="off" />
        <label for="rate-form-from">From (blank: from the start)</label>
        <input id="rate-form-from" type="date" data-testid="rate-form-from" formControlName="from" />
        <label for="rate-form-to">To (blank: does not end)</label>
        <input id="rate-form-to" type="date" data-testid="rate-form-to" formControlName="to" />
        <button type="submit" data-testid="rate-form-submit" [disabled]="saving()">Set rate</button>
        @if (error(); as err) {
          <p role="alert" data-testid="rate-form-error">{{ err }}</p>
        }
      </form>

      <form [formGroup]="previewForm" (ngSubmit)="preview()" aria-label="Preview a rate">
        <label for="rate-preview-grade">Grade</label>
        <select id="rate-preview-grade" data-testid="rate-preview-grade" formControlName="grade">
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <label for="rate-preview-pct">Candidate rate (%)</label>
        <input id="rate-preview-pct" data-testid="rate-preview-pct" formControlName="pct" inputmode="decimal" autocomplete="off" />
        <button type="submit" data-testid="rate-preview" [disabled]="previewing()">Preview</button>
        @if (previewed(); as p) {
          <p aria-live="polite">
            Claims that would change: <span data-testid="rate-preview-count">{{ p.count }}</span>,
            difference: <span data-testid="rate-preview-diff">{{ p.diff }}</span>
          </p>
        }
        @if (previewError(); as err) {
          <p role="alert" data-testid="rate-preview-error">{{ err }}</p>
        }
      </form>
    </section>
  `,
})
export class RatesPanel {
  private readonly sheets = inject(Sheets);
  protected readonly rates = inject(Rates);

  protected readonly grades = GRADES;
  protected readonly notAvailable = NOT_AVAILABLE;
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);

  protected readonly form = new FormGroup({
    grade: new FormControl<Grade>('A', { nonNullable: true }),
    pct: new FormControl('', { nonNullable: true }),
    from: new FormControl('', { nonNullable: true }),
    to: new FormControl('', { nonNullable: true }),
  });

  protected readonly previewForm = new FormGroup({
    grade: new FormControl<Grade>('A', { nonNullable: true }),
    pct: new FormControl('', { nonNullable: true }),
  });
  protected readonly previewed = signal<RatePreview | null>(null);
  protected readonly previewError = signal<string | null>(null);
  protected readonly previewing = signal(false);

  constructor() {
    // Each (re)load of a sheet re-reads its rates from the store.
    toObservable(this.sheets.loaded)
      .pipe(
        switchMap((sheet) => {
          this.error.set(null);
          this.previewed.set(null);
          this.previewError.set(null);
          return this.rates.load(sheet?.id ?? null) ?? EMPTY;
        }),
        takeUntilDestroyed(),
      )
      .subscribe({ error: () => this.error.set('Could not read the rates.') });
    // An error is removed as soon as its form is changed.
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
    this.previewForm.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.previewError.set(null));
  }

  protected preview(): void {
    if (this.previewing()) return;
    // A press clears the last result, so two presses with the same result can be told apart.
    this.previewed.set(null);
    this.previewError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const { grade, pct } = this.previewForm.getRawValue();
    const rate = pct.trim();
    if (!RATE_PATTERN.test(rate)) {
      this.previewError.set('Type a rate of 0.00 or more, with up to two decimals.');
      return;
    }
    this.previewing.set(true);
    this.rates.preview(sheet.id, grade, rate).subscribe({
      next: (result) => {
        this.previewing.set(false);
        this.previewed.set(result);
      },
      error: () => {
        this.previewing.set(false);
        this.previewError.set('Could not preview that rate.');
      },
    });
  }

  protected submit(): void {
    // A second submit before the first has answered is ignored, so it stores one record.
    if (this.saving()) return;
    this.error.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const { grade, pct, from, to } = this.form.getRawValue();
    const rate = pct.trim();
    if (!RATE_PATTERN.test(rate)) {
      this.error.set('Type a rate of 0.00 or more, with up to two decimals.');
      return;
    }
    if (from !== '' && to !== '' && to < from) {
      this.error.set('A rate cannot end before it starts.');
      return;
    }
    this.saving.set(true);
    this.rates.set(sheet.id, grade, rate, from === '' ? null : from, to === '' ? null : to).subscribe({
      next: () => {
        this.saving.set(false);
        this.form.reset({ grade, pct: '', from: '', to: '' }, { emitEvent: false });
      },
      error: () => {
        this.saving.set(false);
        this.error.set('Could not set that rate.');
      },
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { Observable, forkJoin, map, tap } from 'rxjs';
import { ClaimStatus, addDays, cents, isOverdue } from './claims';
import { Grade } from './people';
import { SheetView, Sheets, graceOn, settingOn } from './sheet';

/** What a candidate rate would change: how many claims would show a different due, and the sum of the differences
 *  (two decimals, negative when lower). */
export interface RatePreview {
  count: number;
  diff: string;
}

export interface RateView {
  grade: Grade;
  /** The percent with exactly two decimals, e.g. "12.50". */
  rate: string;
  /** The day it takes effect (yyyy-mm-dd); null when it applies from the beginning of time. */
  from: string | null;
  /** The last day it applies (yyyy-mm-dd); null when it does not end. */
  to: string | null;
}

/** The rate among a grade's rates (in the order they take effect) in force on a date (yyyy-mm-dd):
 *  the one with the latest from-date on or before it, unless the date is after its to-date; undefined
 *  when the date is before them all, or that rate has ended by then (an earlier one does not take over again). */
export function rateOn(gradeRates: readonly RateView[], date: string): string | undefined {
  let inForce: RateView | undefined;
  for (const r of gradeRates) if (r.from === null || r.from <= date) inForce = r;
  return inForce === undefined || (inForce.to !== null && inForce.to < date) ? undefined : inForce.rate;
}

/** A grade's rates on a sheet, then on each of its ancestors (its parent, its parent's parent, up to three levels
 *  up), each in the order they take effect. */
export type RateLine = readonly (readonly RateView[])[];

/** The rate of a grade in force on a date (yyyy-mm-dd) along its line: the sheet's own, else the nearest ancestor's;
 *  undefined when no sheet in the line has one. */
export function rateOnLine(line: RateLine, date: string): string | undefined {
  for (const gradeRates of line) {
    const rate = rateOn(gradeRates, date);
    if (rate !== undefined) return rate;
  }
  return undefined;
}

/** Rates in the order they take effect: the one with no from-date first, then by from-date. */
function byFrom(a: RateView, b: RateView): number {
  return a.from === b.from ? 0 : a.from === null ? -1 : b.from === null ? 1 : a.from < b.from ? -1 : 1;
}

/** A rate the form accepts: a percent of 0.00 or more, up to 999.99, with up to two decimals. */
export const RATE_PATTERN = /^\d{1,3}(\.\d{1,2})?$/;

/** The floor a sheet starts with. */
export const DEFAULT_FLOOR = '1.00';

/** The due terms used before a sheet is loaded: its starting floor and no late charge. */
export const DEFAULT_DUE_TERMS: DueTerms = { today: '', policyDate: null, settings: [] };

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

/** What is shown in place of a due when its grade has no rate. */
export const NOT_AVAILABLE = 'n/a';

/** The due on an amount (in whole cents) at a rate (a percent, e.g. "12.50"), in whole cents:
 *  amount × rate / 100, rounded to the cent half to even, or half up when `halfUp` (a negative amount as its
 *  opposite is, negated). Exact, whatever the size of the amount. */
export function dueCents(amountCents: number, rate: string, halfUp = false): number {
  if (amountCents < 0) return -dueCents(-amountCents, rate, halfUp);
  const [whole, frac = ''] = rate.split('.');
  const basisPoints = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0').slice(0, 2));
  const product = BigInt(amountCents) * basisPoints;
  const quotient = product / 10000n;
  const remainder = product % 10000n;
  const roundUp = remainder > 5000n || (remainder === 5000n && (halfUp || quotient % 2n === 1n));
  return Number(roundUp ? quotient + 1n : quotient);
}

/** The sheet's settings a claim's due depends on: its dated floors and late percents, its policy date and, for
 *  the late charge, its today. */
export type DueTerms = Pick<SheetView, 'today' | 'policyDate' | 'settings'>;

/** The floor in force on a claim's date (yyyy-mm-dd). */
export function floorOn(sheet: DueTerms, date: string): string {
  return settingOn(sheet.settings, 'floor', date, DEFAULT_FLOOR);
}

/** The late percent in force on a date (yyyy-mm-dd). */
export function latePctOn(sheet: DueTerms, date: string): string {
  return settingOn(sheet.settings, 'late-pct', date, DEFAULT_LATE_PCT);
}

/** Whether a claim whose figures round by this date (yyyy-mm-dd) rounds half up: it is before the sheet's policy
 *  date (its today when it has none); on or after it, it rounds half to even. */
export function roundsHalfUp(date: string, sheet: DueTerms): boolean {
  return date < (sheet.policyDate ?? sheet.today);
}

/** The late charge an OPEN or PENDING claim, not deferred, has gained on its figure (in whole cents) by the sheet's today:
 *  for each full 30 days past its due-by plus its grade's grace days, the late percent in force on that boundary date
 *  (that day plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries before it (compounding),
 *  rounded as the claim rounds, added up. A correction (a negative amount) gains none. */
export function lateChargeCents(
  c: { amount: string; date: string; dueBy: string; status: ClaimStatus; deferredUntil: string | null },
  figureCents: number,
  sheet: DueTerms,
  graceDays = 0,
): number {
  if (cents(c.amount) < 0 || !isOverdue(c, sheet.today, graceDays)) return 0;
  const from = addDays(c.dueBy, graceDays);
  const days = (Date.parse(sheet.today) - Date.parse(from)) / 86_400_000;
  const periods = Math.floor(days / 30);
  const halfUp = roundsHalfUp(c.date, sheet);
  let charge = 0;
  for (let k = 1; k <= periods; k++) {
    const boundary = addDays(from, k * 30);
    charge += dueCents(figureCents + charge, latePctOn(sheet, boundary), halfUp);
  }
  return charge;
}

/** A claim's due in whole cents: the figure fixed when it was settled, else the figure its person's
 *  last statement binds it to (none: n/a), else its amount at its grade's rate in force on its date (the sheet's own, else its nearest ancestor's), with any late
 *  charge added on top of it, the sum raised to the floor in force on its date (a correction is not); null when it has none. Its live
 *  figure rounds by `roundsOn`: its date, or for a correction the date of the claim it corrects. `grade` is its
 *  person's grade in force on its date, whose grace days delay its late charge. */
export function claimDueCents(
  c: { amount: string; date: string; dueBy: string; status: ClaimStatus; deferredUntil: string | null; settledDue: string | null; stated: boolean; statedDue: string | null },
  gradeRates: RateLine,
  sheet: DueTerms,
  roundsOn: string,
  grade: Grade,
): number | null {
  if (c.settledDue !== null) return cents(c.settledDue);
  let figure: number;
  if (c.stated && c.status !== 'PENDING') {
    // A statement binds the claim to its figure then, or to none (n/a).
    if (c.statedDue === null) return null;
    figure = cents(c.statedDue);
  } else {
    const rate = rateOnLine(gradeRates, c.date);
    if (rate === undefined) return null;
    figure = dueCents(cents(c.amount), rate, roundsHalfUp(roundsOn, sheet));
  }
  const due = figure + lateChargeCents(c, figure, sheet, graceOn(sheet.settings, grade, c.date));
  return cents(c.amount) < 0 ? due : Math.max(due, cents(floorOn(sheet, c.date)));
}


// The rates set for each grade on the active sheet, by from-date, and those of its ancestors; a grade with none on
// any of them has no rate.
@Injectable({ providedIn: 'root' })
export class Rates {
  private readonly http = inject(HttpClient);
  private readonly sheets = inject(Sheets);
  private readonly list = signal<RateView[]>([]);
  /** The rates of the active sheet's ancestors, nearest first. */
  private readonly inherited = signal<RateView[][]>([]);
  /** The active sheet's rates of each grade, in the order they take effect. */
  readonly ratesByGrade = computed(() => {
    const byGrade = new Map<Grade, RateView[]>();
    for (const r of [...this.list()].sort(byFrom)) byGrade.set(r.grade, [...(byGrade.get(r.grade) ?? []), r]);
    return byGrade;
  });
  /** Each grade's line of rates: the active sheet's own, then each ancestor's, each in the order they take effect. */
  readonly lineByGrade = computed(() => {
    const levels = [this.list(), ...this.inherited()];
    const grades = new Set(levels.flat().map((r) => r.grade));
    const byGrade = new Map<Grade, RateView[][]>();
    for (const grade of grades) {
      byGrade.set(grade, levels.map((level) => level.filter((r) => r.grade === grade).sort(byFrom)));
    }
    return byGrade;
  });
  /** The rate of each grade in force on the active sheet's today, the sheet's own else its nearest ancestor's; a
   *  grade with none is missing. */
  readonly byGrade = computed(() => {
    const today = this.sheets.current()?.today ?? '';
    const current = new Map<Grade, string>();
    for (const [grade, line] of this.lineByGrade()) {
      const rate = rateOnLine(line, today);
      if (rate !== undefined) current.set(grade, rate);
    }
    return current;
  });

  /** Re-read a sheet's rates, and its ancestors', from the store; null clears them. */
  load(sheetId: string | null): Observable<RateView[]> | null {
    this.list.set([]);
    this.inherited.set([]);
    if (sheetId === null) return null;
    return forkJoin([this.http.get<RateView[]>(this.base(sheetId)), this.fetchInherited(sheetId)]).pipe(
      tap(([rates, inherited]) => {
        this.list.set(rates);
        this.inherited.set(inherited);
      }),
      map(([rates]) => rates),
    );
  }

  /** Re-read the rates of a sheet's ancestors from the store (after its parent changes). */
  loadInherited(sheetId: string): Observable<RateView[][]> {
    return this.fetchInherited(sheetId).pipe(tap((inherited) => this.inherited.set(inherited)));
  }

  private fetchInherited(sheetId: string): Observable<RateView[][]> {
    return this.http.get<RateView[][]>(`${this.base(sheetId)}/inherited`);
  }

  /** Set a grade's rate from a date (null: from the beginning of time) through a to-date (null: it does not end),
   *  replacing the one it had from that date. */
  set(sheetId: string, grade: Grade, rate: string, from: string | null, to: string | null): Observable<RateView> {
    return this.http
      .put<RateView>(`${this.base(sheetId)}/${grade}`, { rate, from, to })
      .pipe(
        tap((saved) =>
          this.list.update((list) => [...list.filter((r) => r.grade !== saved.grade || r.from !== saved.from), saved]),
        ),
      );
  }

  /** What a candidate rate for a grade, applied on every date, would change; nothing is saved. */
  preview(sheetId: string, grade: Grade, rate: string): Observable<RatePreview> {
    return this.http.get<RatePreview>(`${this.base(sheetId)}/${grade}/preview`, { params: { rate } });
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }
}

